#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int maxActivities(vector<vector<int>>& activities) {
    // sort by end time
    sort(activities.begin(), activities.end(), [](vector<int>& a, vector<int>& b) {
        return a[1] < b[1];
    });

    int count = 1;
    int lastEnd = activities[0][1];

    for (int i = 1; i < activities.size(); i++) {
        if (activities[i][0] >= lastEnd) {   // starts after last ends
            count++;
            lastEnd = activities[i][1];
        }
    }
    return count;
}

int main() {
    vector<vector<int>> activities = {{1, 3}, {2, 5}, {4, 7}, {1, 8}, {5, 9}, {8, 10}};
    cout << maxActivities(activities) << endl;
    return 0;
}

