    List<int[]> result = new ArrayList<>();
    int[] curr = intervals[0];

    for (int i = 1; i < intervals.length; i++) {
        if (intervals[i][0] <= curr[1]) {
            curr[1] = Math.max(curr[1], intervals[i][1]);  // extend
        } else {
            result.add(curr);       // no overlap, save current
            curr = intervals[i];    // start new interval
        }
    }

    result.add(curr);
    return result.toArray(new int[0][]);
}

