    intervals.sort(key=lambda a: a[0])  # sort by start

    result = []
    curr = intervals[0][:]

    for i in range(1, len(intervals)):
        if intervals[i][0] <= curr[1]:
            curr[1] = max(curr[1], intervals[i][1])  # extend
        else:
            result.append(curr)       # no overlap, save current
            curr = intervals[i][:]    # start new interval

    result.append(curr)
    return result


if __name__ == "__main__":
